function escapeCsv(value: unknown) {
  const text = String(value ?? '');
  if (/[",\n]/.test(text)) return `"${text.replaceAll('"', '""')}"`;
  return text;
}

export const testImportCsv = [
  promotionTargetImportColumns.join(','),
  ...testImportRows.map((row) => promotionTargetImportColumns.map((column) => escapeCsv(row[column as keyof typeof row])).join(','))
].join('\n');
